USE `cinemabooking`;

SET FOREIGN_KEY_CHECKS = 0;

-- 1. Cập nhật sức chứa phòng chiếu lên 84
UPDATE `rooms` SET `Capacity` = 84 WHERE `RoomID` IN (1, 2, 3, 4, 5);

-- 2. Dọn dữ liệu vé cũ
DELETE FROM `tickets`;
DELETE FROM `bookingfoods`;
DELETE FROM `payments`;
DELETE FROM `bookings`;

-- 3. Xóa và làm mới bảng ghế
DELETE FROM `seats` WHERE `RoomID` IN (1, 2, 3, 4, 5);
ALTER TABLE `seats` AUTO_INCREMENT = 1;

